$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$route = Decode ""

$targetDir = Join-Path $root "app\api\market\requests\[id]\split-fallback"
$targetPath = Join-Path $targetDir "route.ts"
$jobsHelper = Join-Path $root "lib\provider-jobs-live-revalidation.ts"
$groupRoute = Join-Path $root "app\api\market\requests\[id]\group-booking\route.ts"
$financeRoute = Join-Path $root "app\api\provider\finance\route.ts"

foreach ($path in @($jobsHelper, $groupRoute, $financeRoute)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.15 : fichier requis introuvable : $path"
    }
}

$jobs = [System.IO.File]::ReadAllText($jobsHelper)
$group = [System.IO.File]::ReadAllText($groupRoute)
$finance = [System.IO.File]::ReadAllText($financeRoute)

if (-not $jobs.Contains("KLYX_PROVIDER_JOBS_LIVE_ELIGIBILITY_13_08")) {
    throw "13.15 : KLYX 13.08 introuvable."
}

if (-not $group.Contains("KLYX_GROUP_BOOKING")) {
    Write-Host "13.15 : marker group booking generique non trouve, verification RPC..."

    if (-not $group.Contains("klyx_create_multi_slot_booking_group")) {
        throw "13.15 : group booking multi-slot introuvable."
    }
}

if (-not $finance.Contains("KLYX_CANONICAL_FINANCE_TRANSACTIONS_13_11")) {
    throw "13.15 : finance canonique 13.11 introuvable."
}

New-Item -ItemType Directory -Force -Path $targetDir | Out-Null

if (Test-Path -LiteralPath $targetPath) {
    $existing = [System.IO.File]::ReadAllText($targetPath)

    if ($existing.Contains("KLYX_MULTI_PROVIDER_FALLBACK_API_13_15")) {
        Write-Host "KLYX 13.15 deja applique."
        exit 0
    }

    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    Copy-Item -LiteralPath $targetPath -Destination ($targetPath + ".bak-13-15-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($targetPath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.15 APPLIQUE"
Write-Host "======================================"
Write-Host "Fallback multi-provider : PREPARE"
Write-Host "Prestataire N/N disponible : PRIORITAIRE"
Write-Host "Prestataires partiels : CLASSES"
Write-Host "Somme coverage != preuve slots : RESPECTE"
Write-Host "Mapping par slot : ENCORE REQUIS"
Write-Host "Selection automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
